/// Deal `base` damage to every alive enemy (canonical AoE).
///
/// Delegates to the shared engine helper
/// [`sts2_core::card_effects::deal_damage_to_all_alive_enemies`], which
/// mirrors C# `CreatureCmd.Damage` (`CreatureCmd.cs:134-151` computes
/// `Hook.ModifyDamage` for EVERY target up-front against the constant
/// pre-death dealer state, and `CreatureCmd.cs:285` calls `Kill` only once
/// after the whole loop). Locking each target's damage BEFORE any
/// mid-AoE death means a death-triggered dealer-debuff removal — e.g.
/// ShrinkerBeetle dies to the first hit and its `AfterDeath` strips the
/// player's Shrink (-30% powered-attack) — cannot retroactively inflate a
/// surviving target's already-resolved hit. The old per-enemy
/// compute+kill interleave (`deal_damage_player_to_enemy` in a loop) let
/// the Shrink drop mid-fan and over-damaged later enemies (issue #175,
/// seed 2080: GrandFinale over ShrinkerBeetle+Wurm). DaggerSpray calls
/// this twice = two independently-locked volleys, matching C# per-hit AoE.
pub(crate) fn deal_damage_player_to_all(state: &mut CombatState, base: i32) {
    let card = sts2_core::card_effects::originating_card_id(state);
    let _ = deal_damage_to_all_alive_enemies(state, base, ValueProps::MOVE, card);
}

/// Apply `amount` stacks of `kind` to the player (self). No-op if amount <= 0.
/// Mirrors the same-named helper in `cards::ironclad`; duplicated here to
/// avoid cross-character helper sharing at this pin. Existing instances
/// stack additively. Used by Abrasive (Dex+Thorns self-buff) and any other
/// Silent power that targets self.
pub(crate) fn apply_power_to_player(state: &mut CombatState, kind: PowerKind, amount: i32) {
    if amount <= 0 {
        return;
    }
    // Bead `sts2-rs-au4l2`: route through the canonical creature surface
    // when the d03 mirror is set, so self-powers stack onto the same
    // instance as relic combat-start grants.
    if let Some(uid) = state.player.creature_uid {
        sts2_core::card_effects::apply_power_to_creature(state, uid, kind, amount);
        return;
    }
    // Legacy fallback: stack into existing instance if present.
    let existing_uid = state
        .player
        .powers
        .iter()
        .copied()
        .find(|uid| state.powers.iter().any(|p| p.id == uid.0 && p.kind == kind));
    if let Some(uid) = existing_uid {
        if let Some(pow) = state.powers.get_mut_by_id(uid.0) {
            pow.amount = pow.amount.saturating_add(amount);
        }
        return;
    }
    let next_id_raw = state
        .powers
        .iter()
        .map(|p| p.id.get())
        .max()
        .map_or(1, |m| m.saturating_add(1));
    let new_id = std::num::NonZeroU32::new(next_id_raw).expect("power id non-zero");
    state.powers.push(Power {
        id: new_id,
        kind,
        amount,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.player.powers.push(PowerUid(new_id));
}

/// Look up the current `amount` of a power on a specific creature (by uid).
/// Returns 0 if the creature has no instance of that power. Used by handlers
/// that gate side effects on whether a stack actually grew (e.g. PiercingWail
/// only drains Strength when its own debuff stack increases).
pub(crate) fn power_amount_on_creature(
    state: &CombatState,
    uid: CreatureUid,
    kind: PowerKind,
) -> i32 {
    let Some(creature) = state.creatures.iter().find(|c| c.id == uid.0) else {
        return 0;
    };
    for puid in &creature.powers {
        if let Some(p) = state.powers.get_by_id(puid.0) {
            if p.kind == kind {
                return p.amount;
            }
        }
    }
    0
}

/// Apply a signed `amount` stack of `kind` directly to a creature,
/// bypassing the `amount <= 0` early-return that
/// `apply_power_to_creature` enforces. Used by handlers that drain
/// stat-style powers (e.g. PiercingWail / Malaise applying
/// `Strength(-6)`). Stacks additively into an existing power instance,
/// or creates a fresh one if the creature has none.
///
/// Bead `sts2-rs-rez`: the canonical
/// `apply_power_to_creature` surface guards against `amount <= 0` to
/// keep no-op power applications from polluting the powers vec; the
/// canonical Python path supports signed deltas for stat-style powers
/// (`Strength`). A future plumbing bead should fold this into
/// `apply_power_signed` on `card_effects`; for now silent.rs ships its
/// own surface so the PiercingWail / Malaise retrofits can land
/// without touching the core API shape.
pub(crate) fn apply_power_signed_to_creature(
    state: &mut CombatState,
    target_uid: CreatureUid,
    kind: PowerKind,
    amount: i32,
) {
    if amount == 0 {
        return;
    }
    // C# `ArtifactPower` negates a Debuff-direction application
    // (`GetTypeForAmount(amount) == Debuff`) and consumes a stack — for an
    // AllowNegative attribute power that is any negative drain (Malaise's
    // `-Strength`). The canonical affliction gate misses these signed drains,
    // so consult the signed-debuff gate here (no-op for positive restores).
    if amount < 0
        && sts2_core::card_effects::try_consume_artifact_for_signed_debuff(
            state, target_uid, amount,
        )
    {
        return;
    }
    let Some(creature_idx) = state
        .creatures
        .iter()
        .position(|c| c.id == target_uid.0 && c.current_hp > 0)
    else {
        return;
    };
    let existing_uid = state.creatures[creature_idx]
        .powers
        .iter()
        .copied()
        .find(|uid| state.powers.iter().any(|p| p.id == uid.0 && p.kind == kind));
    if let Some(uid) = existing_uid {
        let now_zero = if let Some(pow) = state.powers.get_mut_by_id(uid.0) {
            pow.amount = pow.amount.saturating_add(amount);
            pow.amount == 0
        } else {
            false
        };
        if now_zero {
            // C# `PowerModel.ShouldRemoveDueToAmount` (PowerModel.cs:413) removes
            // an `AllowNegative` attribute power (Strength/Dexterity/Focus) at
            // EXACTLY 0 — a negative result keeps it. Malaise draining a
            // STRENGTH(2) enemy by -2 must leave `[POISON, WEAK]`, not
            // `[POISON, STRENGTH(0), WEAK]` (Silent mid-fuzz seeds 911/1592/1838).
            // Mirrors the ironclad/necrobinder signed-power helpers.
            let pid = uid.0;
            state.powers.retain(|p| p.id != pid);
            state.creatures[creature_idx].powers.retain(|u| u.0 != pid);
        }
        return;
    }
    let next_id_raw = state
        .powers
        .iter()
        .map(|p| p.id.get())
        .max()
        .map_or(1, |m| m.saturating_add(1));
    let new_id = std::num::NonZeroU32::new(next_id_raw).expect("power id non-zero");
    state.powers.push(Power {
        id: new_id,
        kind,
        amount,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.creatures[creature_idx].powers.push(PowerUid(new_id));
}

/// Apply `amount` stacks of `kind` to every alive enemy.
pub(crate) fn apply_power_to_all_enemies(state: &mut CombatState, kind: PowerKind, amount: i32) {
    let uids: Vec<CreatureUid> = state.enemy_uids.iter().copied().collect();
    for uid in uids {
        apply_power_to_enemy(state, uid, kind, amount);
    }
}

/// Build the **12-card** Silent starter deck.
///
/// Distribution: 5×`Strike_Silent`, 5×`Defend_Silent`, 1×Neutralize, 1×Survivor.
/// Mirrors `create_silent_starter_deck` in
/// `sts2-rl-agent@01c094d:sts2_env/cards/silent.py:1604-1613`.
#[must_use]
pub fn silent_starter_deck() -> Vec<CardSpec> {
    let mut deck = Vec::with_capacity(12);
    for _ in 0..5 {
        deck.push(crate::cards::silent::strike_silent::spec());
    }
    for _ in 0..5 {
        deck.push(crate::cards::silent::defend_silent::spec());
    }
    deck.push(crate::cards::silent::neutralize::spec());
    deck.push(crate::cards::silent::survivor::spec());
    deck
}
